    private FabricCrashRecoveryProbe(String phase,Path directory)throws Exception{
        this.phase=phase;this.directory=directory.toAbsolutePath().normalize();checkpointPath=this.directory.resolve("checkpoint.json");
        checkpoint=phase.equals("setup")?new LinkedHashMap<>():JSON.readValue(Files.readAllBytes(checkpointPath),Map.class);
        runId=phase.equals("setup")?UUID.randomUUID().toString():string(checkpoint.get("runId"));trace="t027-rpc-"+runId;exchange="inspection.fabric.crash."+runId;finalQueue=exchange+".finalize";anchorQueue=exchange+".anchor";deadExchange=exchange+".dead.events";deadQueue=exchange+".dead";
        reportPath=this.directory.resolve(phase.equals("recover")?"report.json":phase+".json");
        report.put("formatVersion",1);report.put("runId",runId);report.put("phase",phase);report.put("pid",ProcessHandle.current().pid());report.put("startedAt",Instant.now().toString());report.put("passed",false);report.put("checks",checks);report.put("requests",requests);
        if(!phase.equals("setup")){taskId=(String)checkpoint.get("taskId");deviceId=(String)checkpoint.get("deviceId");if(!phase.equals("cleanup")){require(taskId!=null&&deviceId!=null,"durable_fixture_scope_required");}}
    }
    public static void main(String[] args){
        if(args.length!=2||!Set.of("setup","before-submit","after-submit","after-commit","recover","cleanup").contains(args[0])){System.err.println("Usage: FabricCrashRecoveryProbe setup|before-submit|after-submit|after-commit|recover|cleanup <private-run-directory>");System.exit(2);return;}
        FabricCrashRecoveryProbe probe=null;
        try{probe=new FabricCrashRecoveryProbe(args[0],Path.of(args[1]));probe.execute();probe.writeReport();System.out.println("[PASS] T027 Fabric phase: "+probe.phase);}
        catch(Exception failure){if(probe!=null){probe.report.put("passed",false);probe.report.put("failureType",failure.getClass().getSimpleName());if(failure instanceof ProbeFailure)probe.report.put("failedCheck",failure.getMessage());try{probe.writeReport();}catch(Exception ignored){}}System.err.println("[FAIL] T027 Fabric phase; inspect private safe report");System.exit(1);}
    }
    private void execute()throws Exception{
        openDatabase();require(count("SELECT COUNT(*) FROM flyway_schema_history WHERE success=1 AND version IS NOT NULL")==14,"fourteen_existing_migrations");
        if(phase.equals("setup")){
            require(count("SELECT COUNT(*) FROM outbox_event WHERE status<>'SENT'")==0&&count("SELECT COUNT(*) FROM consumed_event WHERE status<>'DONE'")==0&&count("SELECT COUNT(*) FROM chain_submission WHERE status IN ('PENDING','SUBMITTED','UNKNOWN') OR (status='FAILED' AND retryable=1 AND next_action_at IS NOT NULL)")==0&&count("SELECT COUNT(*) FROM upload_session WHERE status<>'COMPLETED'")==0&&count("SELECT COUNT(*) FROM storage_cleanup_task WHERE status IN ('PENDING','SENDING')")==0,"no_foreign_pending_business_before_setup");
            checkpoint.put("runId",runId);checkpoint.put("baselineSha256",snapshot());checkpoint.put("businessCountsBefore",counts());checkpoint.put("accountIds",new ArrayList<String>());checkpoint.put("uploadIds",new ArrayList<String>());checkpoint.put("fixed",new ArrayList<Map<String,Object>>());checkpoint.put("crashes",new LinkedHashMap<String,Object>());writeCheckpoint();
        }else if(phase.equals("recover")){verifyAllDurableCrashes();waitForExpiredLeases();}
        boolean automatic=phase.equals("recover");
        try(var context=new SpringApplicationBuilder(UavInspectionApplication.class,FaultConfiguration.class).profiles("local","database","storage","messaging","ledger","fabric-crash-probe").web(WebApplicationType.SERVLET).logStartupInfo(false).run("--server.port=0","--inspection.messaging.exchange="+exchange,"--inspection.messaging.finalize-queue="+finalQueue,"--inspection.messaging.anchor-queue="+anchorQueue,"--inspection.messaging.dead-letter-exchange="+deadExchange,"--inspection.messaging.dead-letter-queue="+deadQueue,"--inspection.messaging.publisher-enabled="+automatic,"--inspection.messaging.recovery-enabled="+automatic,"--inspection.ledger.recovery-enabled="+automatic)){
            jdbc=context.getBean(JdbcTemplate.class);source=context.getBean(DataSource.class);s3=context.getBean(S3Client.class);storage=context.getBean(ObjectStorage.class);realClients=context.getBean("institutionLedgerClients",InstitutionLedgerClients.class);anchors=context.getBean(AnchorProcessor.class);finalizer=context.getBean(FinalizationProcessor.class);publisher=context.getBean(OutboxPublisher.class);rabbit=context.getBean(RabbitTemplate.class);control=context.getBean(Control.class);control.probe=this;
            bucket=context.getEnvironment().getRequiredProperty("inspection.storage.bucket");baseUrl="http://127.0.0.1:"+((ServletWebServerApplicationContext)context).getWebServer().getPort();
            require(!context.getBean("finalizationContainer",SimpleMessageListenerContainer.class).isRunning()&&!context.getBean("anchorContainer",SimpleMessageListenerContainer.class).isRunning(),"consumers_paused_to_prove_default_business_scanner_recovery");
            try(HttpClient client=HttpClient.newBuilder().connectTimeout(Duration.ofSeconds(5)).build()){
                http=client;
                if(phase.equals("setup")){setup();}
                else if(CRASHES.contains(phase)){anchors.process(event(string(fixed(phase).get("submissionId"))));throw new ProbeFailure("expected_rpc_boundary_halt_did_not_occur");}
                else{
                    boolean completed=false;
                    try{
                        if(automatic)recover();
                        report.put("retainedAttempts",safeAttempts());
                        context.getBean(ThreadPoolTaskScheduler.class).shutdown();context.getBean(BusinessRecoveryDispatcher.class).close();context.getBean(ProcessingLeaseKeeper.class).shutdown();
                        require(count("SELECT COUNT(*) FROM chain_submission WHERE id IN (SELECT c.id FROM chain_submission c JOIN evidence_version v ON v.id=c.version_id WHERE v.task_id=?) AND lease_until>UTC_TIMESTAMP(3)",taskId)==0,"no_active_business_worker_before_cleanup");
                        publisher.publishBatch();drainOwned();cleanupFixtures();cleanupTopology();require(string(checkpoint.get("baselineSha256")).equals(snapshot()),"original_twenty_four_tables_all_fields_and_binary_checkpoints_preserved");report.put("originalBusinessDataUnchanged",true);report.put("businessCountsAfter",counts());completed=true;
                    }finally{control.unavailable.set(false);if(!completed)report.put("fixturesPreservedForResume",true);}
                }
            }
        }
        report.put("completedAt",Instant.now().toString());report.put("passed",true);
    }
